/*
 * The marks of the apps in Spade's connector catalogue, by catalogue id: Simple Icons (CC0) and a
 * few from their makers' own sites, as plain path data generated by `scripts/app-icons.ts`, with
 * each mark's source and licence in `app-art/LICENCES.md`. Bundled, never fetched: no app's host
 * learns that someone looked at its name. An app without a mark, and any server the person adds
 * by address, shows `appMonogram` on the same neutral tile.
 *
 * Reached only through `@ace/ui-core/app-icons`, never the package index, so a mark loads only
 * when it is on screen.
 */

export { appArt } from "./app-art/index.gen.ts";
export type { BrandArt, BrandPath } from "./brand-art-types.ts";

/** The first letter or digit of an app's name, upper-cased: what an app with no mark shows. */
export function appMonogram(name: string): string {
  const first = [...name.trim()].find((char) => /[\p{L}\p{N}]/u.test(char));
  return (first ?? "?").toLocaleUpperCase();
}
